# the fs edit moves feature's head after the mount; the commit merges with it
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const { sandbox } = await lf.sandbox.create();
  const ws = await lf.workspace.mount(sandbox, "feature");
  const r = await lf.workspace.exec(ws, "sed -i \"s/Hello world/Hello from the Workspace/\" app/page.tsx");
  console.log(`$ sed … app/page.tsx\n[exit ${r.exitCode}]`);
  console.log("fs.edit README.md", (await lf.fs.edit("feature", "/README.md", "# Website", "# Website (feature)", "edit /README.md")).kind);
  const c = await lf.workspace.commit(ws, "heading: Hello from the Workspace");
  console.log("commit", c.kind, c.merged ? "· was stale, merged with the head first" : "");
  await lf.workspace.unmount(ws);
  await lf.sandbox.close(sandbox);
} finally {
  await lf.close();
}
