# both sides change the heading: the commit is refused Conflict and the Workspace is kept
node --input-type=module <<'JS'
const { LayerFS, isRefusal } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const { sandbox } = await lf.sandbox.create();
  const ws = await lf.workspace.mount(sandbox, "feature");
  console.log(JSON.stringify({ ws: `${sandbox}:${ws.path}` }));
  console.log("fs.edit app/page.tsx", (await lf.fs.edit("feature", "/app/page.tsx", "Hello from the Workspace", "Hello from fs", "edit /app/page.tsx")).kind);
  const r = await lf.workspace.exec(ws, "sed -i \"s/Hello from the Workspace/Hello, Workspace/\" app/page.tsx");
  console.log(`$ sed … app/page.tsx\n[exit ${r.exitCode}]`);
  try {
    await lf.workspace.commit(ws, "heading: Hello, Workspace");
  } catch (error) {
    if (!isRefusal(error, "Conflict")) throw error;
    console.log(`commit refused ${error.code}: ${error.message}`);
    for (const c of error.detail?.conflicts ?? []) console.log(`  ${c.path}`);
  }
} finally {
  await lf.close();
}
