# drop fs's side and the markers, then commit and tear down
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const [sandbox, path] = "{{ws}}".split(":");
  const ws = { sandbox, path };
  const r = await lf.workspace.exec(ws, "sed -i '/Hello from fs\\|^<<<<<<<\\|^=======\\|^>>>>>>>/d' app/page.tsx");
  console.log(`$ sed … app/page.tsx\n[exit ${r.exitCode}]`);
  console.log("commit", (await lf.workspace.commit(ws, "heading: Hello, Workspace (conflict fixed)")).kind);
  await lf.workspace.unmount(ws);
  await lf.sandbox.close(sandbox);
} finally {
  await lf.close();
}
